from pathlib import Path


def replace_once(path, old, new):
    p = Path(path)
    s = p.read_text(encoding='utf-8')
    n = s.count(old)
    if n != 1:
        raise SystemExit(f'{path}: expected exactly one match, got {n}: {old[:100]!r}')
    p.write_text(s.replace(old, new, 1), encoding='utf-8')

